#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT 1024

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    const char *src = argv[1];
    size_t len = strlen(src);
    if (len > MAX_INPUT) len = MAX_INPUT;

    char out[MAX_INPUT + 1];
    size_t out_idx = 0;
    size_t i = 0;

    // Skip leading whitespace
    while (i < len && isspace((unsigned char)src[i])) {
        i++;
    }

    int have_output = 0; // whether any non‑whitespace has been output yet
    int in_whitespace = 0; // whether the previous character was whitespace

    for (; i < len; ++i) {
        unsigned char c = (unsigned char)src[i];
        if (isspace(c)) {
            in_whitespace = 1;
            continue;
        }
        if (have_output && in_whitespace) {
            out[out_idx++] = ' ';
        }
        out[out_idx++] = c;
        have_output = 1;
        in_whitespace = 0;
    }

    out[out_idx] = '\0';

    if (out_idx == 0) {
        puts("EMPTY");
    } else {
        puts(out);
    }
    return 0;
}
